import{_ as t,o as d,c as o,ah as c}from"./chunks/framework.Yx0DUrwu.js";const m=JSON.parse('{"title":"适应性免疫应答","description":"","frontmatter":{},"headers":[],"relativePath":"biology/adaptive-effector-immunity.md","filePath":"biology/adaptive-effector-immunity.md","lastUpdated":1787828013000}'),a={name:"biology/adaptive-effector-immunity.md"};function i(r,e,l,n,s,h){return d(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="适应性免疫应答" tabindex="-1">适应性免疫应答 <a class="header-anchor" href="#适应性免疫应答" aria-label="Permalink to &quot;适应性免疫应答&quot;">​</a></h1><p>适应性免疫应答的主线是：抗原在次级淋巴器官中被呈递给 naive lymphocytes，特异性克隆扩增并分化为 effector cells，随后一部分细胞死亡以结束反应，另一部分成为 memory cells。T cell 和 B cell 应答相互配合，形成针对不同病原体和组织环境的效应模块 [1]。</p><h2 id="t-cell-priming" tabindex="-1">T cell priming <a class="header-anchor" href="#t-cell-priming" aria-label="Permalink to &quot;T cell priming&quot;">​</a></h2><div class="flow-strip"><span>APC 摄取抗原</span><span>APC 成熟迁移</span><span>淋巴结内相遇</span><span>TCR 识别 peptide-MHC</span><span>共刺激</span><span>细胞因子极化</span><span>克隆扩增</span><span>效应/记忆分化</span></div><p>T cell activation 通常需要三类信息：TCR specificity、costimulation 和 cytokine environment。单细胞数据中如果只看到 <code>CD3D</code>、<code>CD4</code> 或 <code>CD8A</code>，只能说明谱系；判断功能状态还要看 cytokines、transcription factors、cytotoxic genes、checkpoint receptors 和 clonal expansion。</p><h2 id="cd4-t-cell-效应模块" tabindex="-1">CD4 T cell 效应模块 <a class="header-anchor" href="#cd4-t-cell-效应模块" aria-label="Permalink to &quot;CD4 T cell 效应模块&quot;">​</a></h2><table tabindex="0"><thead><tr><th>亚群</th><th>关键因子</th><th>典型功能</th><th>常见 marker / genes</th></tr></thead><tbody><tr><td>Th1</td><td>IL-12, IFN-gamma, T-bet</td><td>激活 macrophage，对付胞内病原。</td><td><code>TBX21</code>, <code>IFNG</code>, <code>CXCR3</code></td></tr><tr><td>Th2</td><td>IL-4, GATA3</td><td>驱虫、过敏、屏障修复。</td><td><code>GATA3</code>, <code>IL4</code>, <code>IL5</code>, <code>IL13</code></td></tr><tr><td>Th17</td><td>IL-6, IL-23, TGF-beta, RORC</td><td>对付胞外菌和真菌，驱动屏障炎症。</td><td><code>RORC</code>, <code>IL17A</code>, <code>IL17F</code>, <code>CCR6</code></td></tr><tr><td>Tfh</td><td>BCL6, ICOS, CXCR5</td><td>帮助 B cell 生发中心反应、类别转换和亲和力成熟。</td><td><code>CXCR5</code>, <code>ICOS</code>, <code>BCL6</code>, <code>IL21</code></td></tr><tr><td>Treg</td><td>FOXP3, IL2RA, CTLA4</td><td>抑制过强或自身反应性免疫。</td><td><code>FOXP3</code>, <code>IL2RA</code>, <code>CTLA4</code>, <code>IKZF2</code></td></tr></tbody></table><h2 id="cd8-t-cell-和细胞毒性" tabindex="-1">CD8 T cell 和细胞毒性 <a class="header-anchor" href="#cd8-t-cell-和细胞毒性" aria-label="Permalink to &quot;CD8 T cell 和细胞毒性&quot;">​</a></h2><p>CD8 cytotoxic T cells 通过 perforin/granzyme pathway 或 death receptor pathway 杀伤靶细胞。单细胞中常见 cytotoxic program 包括 <code>NKG7</code>, <code>PRF1</code>, <code>GZMB</code>, <code>GZMH</code>, <code>GNLY</code>。但 cytotoxic genes 同时可见于 NK cells，所以注释时要结合 TCR/CD3 genes 与 NK receptor genes。</p><div class="doc-callout warning"><strong>耗竭需要组合证据</strong><p>`PDCD1`、`LAG3`、`TIGIT`、`HAVCR2`、`TOX` 等可以提示 exhaustion-like state，但感染、肿瘤、近期激活和组织驻留都会改变这些基因。最好结合 clonotype、effector genes、样本来源和功能证据。</p></div><h2 id="b-cell、抗体和生发中心" tabindex="-1">B cell、抗体和生发中心 <a class="header-anchor" href="#b-cell、抗体和生发中心" aria-label="Permalink to &quot;B cell、抗体和生发中心&quot;">​</a></h2><p>B cell activation 可以是 T-dependent，也可以是 T-independent。T-dependent response 中，B cell 捕获抗原后向 Tfh 提呈，得到 CD40 和 cytokine help，进入 germinal center，经历 somatic hypermutation、affinity maturation 和 class switch recombination。</p><table tabindex="0"><thead><tr><th>阶段</th><th>关键事件</th><th>单细胞线索</th></tr></thead><tbody><tr><td>activation</td><td>antigen binding, T-B linked recognition</td><td><code>CD69</code>, <code>CD83</code>, <code>HLA-DRA</code>, <code>CD40</code></td></tr><tr><td>germinal center</td><td>proliferation, mutation, selection</td><td><code>BCL6</code>, <code>AICDA</code>, <code>MKI67</code></td></tr><tr><td>class switching</td><td>IgM/IgD 转向 IgG/IgA/IgE</td><td><code>IGHG*</code>, <code>IGHA*</code>, <code>IGHE</code></td></tr><tr><td>plasma differentiation</td><td>antibody secretion</td><td><code>XBP1</code>, <code>MZB1</code>, <code>JCHAIN</code>, <code>SDC1</code></td></tr><tr><td>memory formation</td><td>rapid secondary response</td><td><code>CD27</code>, switched isotypes</td></tr></tbody></table><h2 id="免疫记忆" tabindex="-1">免疫记忆 <a class="header-anchor" href="#免疫记忆" aria-label="Permalink to &quot;免疫记忆&quot;">​</a></h2><p>Memory B cells 通常比 naive B cells 更快启动，并可在二次应答中继续亲和力成熟。Memory T cells 可粗略分为 central memory、effector memory 和 tissue-resident memory。单细胞里不要只按 <code>CCR7</code> 或 <code>IL7R</code> 单基因判断；最好结合 homing receptors、effector genes、tissue residency genes 和样本组织来源。</p><h2 id="自检问题" tabindex="-1">自检问题 <a class="header-anchor" href="#自检问题" aria-label="Permalink to &quot;自检问题&quot;">​</a></h2><ol><li>T cell priming 为什么需要 APC 成熟和共刺激？</li><li>Th1、Th2、Th17 分别适合应对哪类威胁？</li><li>Tfh 如何影响 B cell class switching 和 affinity maturation？</li><li>CD8 T cell 和 NK cell 的 cytotoxic gene program 如何区分？</li></ol><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p>[1] Murphy, K. &amp; Weaver, C. <em>Janeway&#39;s Immunobiology</em>. 9th ed. Garland Science (2017). 中文版：《詹韦免疫生物学：原书第九版》，科学出版社，2022。</p>',19)])])}const C=t(a,[["render",i]]);export{m as __pageData,C as default};
